void PS2Runtime::Store128(uint8_t *rdram, R5900Context *ctx, uint32_t vaddr, __m128i value)
{
    alignas(16) uint64_t _parts[2];
    _mm_storeu_si128(reinterpret_cast<__m128i *>(_parts), value);
    ps2TraceGuestWrite(rdram, vaddr, 16u, _parts[0], _parts[1], "WRITE128", ctx);
    try
    {
        m_memory.write128(vaddr, value);
        drainCompletedDmacHandlers(rdram);
    }
    catch (const std::exception &e)
    {
        reportGuestMemoryFault(ctx, "store128", vaddr, e.what());
        SignalException(ctx, EXCEPTION_ADDRESS_ERROR_STORE);
    }
}

void PS2Runtime::kickGifDmaChainFromMMIO(uint8_t *rdram,
                                         R5900Context *ctx,
                                         uint32_t dPcrValue,
                                         uint32_t dStatValue,
                                         uint32_t tadr,
                                         uint32_t chcr)
{
    constexpr uint32_t D_PCR = 0x1000E020u;
    constexpr uint32_t D_STAT = 0x1000E010u;
    constexpr uint32_t GIF_TADR = 0x1000A030u;
    constexpr uint32_t GIF_CHCR = 0x1000A000u;

    ps2TraceGuestWrite(rdram, D_PCR, 4u, dPcrValue, 0u, "WRITE32", ctx);
    m_memory.writeIORegister(D_PCR, dPcrValue);
    ps2TraceGuestWrite(rdram, D_STAT, 4u, dStatValue, 0u, "WRITE32", ctx);
    m_memory.writeIORegister(D_STAT, dStatValue);
    ps2TraceGuestWrite(rdram, GIF_TADR, 4u, tadr, 0u, "WRITE32", ctx);
    m_memory.writeIORegister(GIF_TADR, tadr);
    ps2TraceGuestWrite(rdram, GIF_CHCR, 4u, chcr, 0u, "WRITE32", ctx);
    if (m_memory.tryProcessNativeGifImageUploadChain(m_gs, tadr, chcr))
    {
        drainCompletedDmacHandlers(rdram);
        return;
    }
    if (m_memory.tryProcessNativeGifPackedChain(m_gs, tadr, chcr))
    {
        drainCompletedDmacHandlers(rdram);
        return;
    }
    m_memory.writeIORegister(GIF_CHCR, chcr);
    m_memory.processPendingTransfers();
    drainCompletedDmacHandlers(rdram);
}

void PS2Runtime::requestStop()
{
    m_stopRequested.store(true, std::memory_order_relaxed);
    if (m_eeScheduler)
    {
        m_eeScheduler->requestStop();
    }
}

bool PS2Runtime::isStopRequested() const
{
    return m_stopRequested.load(std::memory_order_relaxed);
}

EeScheduler &PS2Runtime::eeScheduler()
{
    return *m_eeScheduler;
}

const EeScheduler &PS2Runtime::eeScheduler() const
{
    return *m_eeScheduler;
}

void PS2Runtime::postEeEvent(EeEvent event)
{
    m_eeScheduler->postEvent(event);
}

bool PS2Runtime::eeCheckpointDue(uint32_t cycles) noexcept
{
    const bool due = m_eeScheduler->checkpointDue(cycles);
    if (due)
    {
        markDispatchUnwind();
    }
    return due;
}

[[noreturn]] void PS2Runtime::eeWaitVSyncTicks(uint32_t ticks, uint32_t resumePc)
{
    const uint64_t currentTick = m_eeScheduler->currentVSyncTick();
    const uint64_t waitTicks = std::max<uint64_t>(1u, ticks);
    m_eeScheduler->waitVSync(currentTick + waitTicks - 1u,
                             0,
                             [resumePc](R5900Context &context)
                             {
                                 context.pc = resumePc;
                             });
}

void PS2Runtime::addEeExitHandler(int threadId, uint32_t function, uint32_t argument)
{
    std::lock_guard lock(m_eeKernelStateMutex);
    m_eeExitHandlers[threadId].push_back({function, argument});
}

std::vector<PS2Runtime::EeExitHandlerRegistration> PS2Runtime::takeEeExitHandlers(int threadId)
{
    std::lock_guard lock(m_eeKernelStateMutex);
    auto it = m_eeExitHandlers.find(threadId);
    if (it == m_eeExitHandlers.end())
    {
        return {};
    }
    auto handlers = std::move(it->second);
    m_eeExitHandlers.erase(it);
    return handlers;
}

void PS2Runtime::removeEeExitHandlers(int threadId)
{
    std::lock_guard lock(m_eeKernelStateMutex);
    m_eeExitHandlers.erase(threadId);
}

bool PS2Runtime::findEeSyscallOverride(uint32_t syscallNumber, uint32_t &handler) const
{
    std::lock_guard lock(m_eeKernelStateMutex);
    const auto it = m_eeSyscallOverrides.find(syscallNumber);
    if (it == m_eeSyscallOverrides.end())
    {
        return false;
    }
    handler = it->second;
    return true;
}

void PS2Runtime::setEeSyscallOverride(uint8_t *rdram, uint32_t syscallNumber, uint32_t handler)
{
    constexpr uint32_t kTableBase = 0x80011F80u & 0x1FFFFFFFu;
    constexpr uint32_t kMirrorLimit = 0x00080000u;
    const int64_t offset = static_cast<int64_t>(static_cast<int32_t>(syscallNumber)) * 4;
    const int64_t address = static_cast<int64_t>(kTableBase) + offset;

    std::lock_guard lock(m_eeKernelStateMutex);
    if (handler == 0u)
    {
        m_eeSyscallOverrides.erase(syscallNumber);
    }
    else
    {
        m_eeSyscallOverrides[syscallNumber] = handler;
    }
    if (!rdram || address < 0 || address + 4 > kMirrorLimit)
    {
        return;
    }
    const uint32_t guestAddress = static_cast<uint32_t>(address);
    std::memcpy(rdram + guestAddress, &handler, sizeof(handler));
    if (handler == 0u)
    {
        m_eeSyscallMirrorAddresses.erase(guestAddress);
    }
    else
    {
        m_eeSyscallMirrorAddresses.insert(guestAddress);
    }
}

bool PS2Runtime::noteUnrunnableSyscallOverride(uint32_t syscallNumber, uint32_t handler)
{
    const uint64_t key = (static_cast<uint64_t>(syscallNumber) << 32) | static_cast<uint64_t>(handler);
    std::lock_guard lock(m_eeKernelStateMutex);
    if (m_unrunnableSyscallOverrides.size() >= kMaxUnrunnableSyscallOverridesReported &&
        m_unrunnableSyscallOverrides.find(key) == m_unrunnableSyscallOverrides.end())
    {
        return false;
    }
    return m_unrunnableSyscallOverrides.insert(key).second;
}

void PS2Runtime::initializeEeKernelState(uint8_t *rdram)
{
    if (!rdram)
    {
        return;
    }
    constexpr uint32_t kTableGuestBase = 0x80011F80u;
    constexpr uint32_t kTableBase = kTableGuestBase & 0x1FFFFFFFu;
    constexpr uint32_t kMirrorLimit = 0x00080000u;
    constexpr uint32_t kProbeBase = 0x000002F0u;

    std::lock_guard lock(m_eeKernelStateMutex);
    // The guest kernel is starting over, so the "override we cannot execute" diagnostic starts
    // over with it.
    m_unrunnableSyscallOverrides.clear();
    for (const uint32_t address : m_eeSyscallMirrorAddresses)
    {
        const uint32_t zero = 0u;
        std::memcpy(rdram + address, &zero, sizeof(zero));
    }
    m_eeSyscallMirrorAddresses.clear();
    const uint32_t high = kTableGuestBase >> 16;
    const uint32_t low = kTableGuestBase & 0xFFFFu;
    std::memcpy(rdram + kProbeBase, &high, sizeof(high));
    std::memcpy(rdram + kProbeBase + 8u, &low, sizeof(low));
    m_eeSyscallMirrorAddresses.insert(kProbeBase);
    m_eeSyscallMirrorAddresses.insert(kProbeBase + 8u);

    for (const auto &[syscallNumber, handler] : m_eeSyscallOverrides)
    {
        const int64_t offset = static_cast<int64_t>(static_cast<int32_t>(syscallNumber)) * 4;
        const int64_t address = static_cast<int64_t>(kTableBase) + offset;
        if (address < 0 || address + 4 > kMirrorLimit)
        {
            continue;
        }
        const uint32_t guestAddress = static_cast<uint32_t>(address);
        std::memcpy(rdram + guestAddress, &handler, sizeof(handler));
        m_eeSyscallMirrorAddresses.insert(guestAddress);
    }
}

void PS2Runtime::HandleIntegerOverflow(R5900Context *ctx)
{
    raiseCop0Exception(ctx, EXCEPTION_INTEGER_OVERFLOW);
}

void PS2Runtime::run()
{
    m_stopRequested.store(false, std::memory_order_relaxed);
    ps2_stubs::resetSifState();
    resetIop();
    ps2_stubs::resetAudioStubState();
    ps2_stubs::resetMpegStubState();
    resetStubRuntimeState();   // Sprint 11 Task 8b review N1: the stub *RuntimeState group
    initializeEeKernelState(m_memory.getRDRAM());
    m_cpuContext.r[4] = _mm_setzero_si128();
    m_cpuContext.r[5] = _mm_setzero_si128();
    m_cpuContext.r[29] = _mm_set_epi64x(0, static_cast<int64_t>(PS2_RAM_SIZE - 0x10u));
    m_debugPc.store(m_cpuContext.pc, std::memory_order_relaxed);
    m_debugRa.store(static_cast<uint32_t>(_mm_extract_epi32(m_cpuContext.r[31], 0)), std::memory_order_relaxed);
    m_debugSp.store(static_cast<uint32_t>(_mm_extract_epi32(m_cpuContext.r[29], 0)), std::memory_order_relaxed);
    m_debugGp.store(static_cast<uint32_t>(_mm_extract_epi32(m_cpuContext.r[28], 0)), std::memory_order_relaxed);

    RUNTIME_LOG("Starting execution at address 0x" << std::hex << m_cpuContext.pc << std::dec);

    // A blank image to use as a framebuffer
    Image blank = GenImageColor(FB_WIDTH, FB_HEIGHT, BLANK);
    Texture2D frameTex = LoadTextureFromImage(blank);
    UnloadImage(blank);

    std::atomic<bool> gameThreadFinished{false};

    std::thread gameThread([&]()
                           {
        ThreadNaming::SetCurrentThreadName("GameThread");
        // The EE FPU and VU0 truncate every result (PCSX2's default "Chop/Zero" rounding for EE
        // and VU); host float math rounds to nearest. Run the game thread with the host FPU/SSE
        // rounding toward zero (2026-09-08: SOCOM II's title-screen labels are composed from an
        // index that only comes out right with chop; PS2X_EE_ROUND=nearest restores the old mode).
        {
            const char *round = ps2x::knob("PS2X_EE_ROUND");
            if (!round || std::strcmp(round, "nearest") != 0)
                std::fesetround(FE_TOWARDZERO);
        }
        try
        {
            m_eeScheduler->reset(m_memory.getRDRAM(), m_cpuContext);
            m_eeScheduler->run();
            uint32_t pc = m_debugPc.load(std::memory_order_relaxed);
            RUNTIME_LOG("Game thread returned. PC=0x" << std::hex << pc
                      << " RA=0x" << static_cast<uint32_t>(_mm_extract_epi32(m_cpuContext.r[31], 0)) << std::dec << std::endl);
        }
        catch (const std::exception &e)
        {
            std::cerr << "Error during program execution: " << e.what() << std::endl;
        }
        catch (...)
        {
            std::cerr << "Error during program execution: unknown exception" << std::endl;
        }
        gameThreadFinished.store(true, std::memory_order_release); });
    // PS2X_HOST_PROF=<ms>: host-level sampling profiler of the game thread (runtime/host_prof_start.h: the runner's
    // sampler when it has one, else the runtime's weak no-op).
    ps2HostProfStart(gameThread.native_handle());

    uint64_t tick = 0;
    while (!isStopRequested() && !gameThreadFinished.load(std::memory_order_acquire))
    {
        PS2_IF_AGRESSIVE_LOGS({
            tick++;
            if ((tick % 120) == 0)
            {
                uint64_t curDma = m_memory.dmaStartCount();
                uint64_t curGif = m_memory.gifCopyCount();
                uint64_t curGs = m_memory.gsWriteCount();
                uint64_t curVif = m_memory.vifWriteCount();
                const GSRegisters &gs = m_memory.gs();
                const uint32_t dbgPc = m_debugPc.load(std::memory_order_relaxed);
                const uint32_t dbgRa = m_debugRa.load(std::memory_order_relaxed);
                const uint32_t dbgSp = m_debugSp.load(std::memory_order_relaxed);
                const uint32_t dbgGp = m_debugGp.load(std::memory_order_relaxed);
                const auto eeSnapshot = m_eeScheduler->snapshot();

                RUNTIME_LOG("[run:tick] tick=" << tick
                                               << " pc=0x" << std::hex << dbgPc
                                               << " ra=0x" << dbgRa
                                               << " sp=0x" << dbgSp
                                               << " gp=0x" << dbgGp
                                               << " dispfb1=0x" << gs.dispfb1
                                               << " display1=0x" << gs.display1
                                               << std::dec
                                               << " activeThreads=" << eeSnapshot.threads.size()
                                               << " dma=" << curDma
                                               << " gif=" << curGif
                                               << " gsw=" << curGs
                                               << " vif=" << curVif
                                               << std::endl);
            }
        });
        uint32_t presentWidth = FB_WIDTH;
        uint32_t presentHeight = DEFAULT_DISPLAY_HEIGHT;
        // GPU backend: replay the game thread's GS command stream on this (GL) thread and draw the
        // presented render target directly; otherwise upload the CPU-rasterized frame.
        Texture2D presentTex = frameTex;
        uint32_t hostTexW = 0u, hostTexH = 0u, hostFullW = 0u, hostFullH = 0u;
        uint32_t hostTex = 0u;
        if (gs().hostDriven())
        {
            // Same vsync-tick gating as UploadFrame: latch (records the GS present), then replay.
            static uint64_t s_gpuLastTick = std::numeric_limits<uint64_t>::max();
            const uint64_t tickNow = eeScheduler().currentVSyncTick();
            if (tickNow != s_gpuLastTick)
            {
                gs().latchHostPresentationFrame();
                s_gpuLastTick = tickNow;
            }
            if (gs().hostRenderFrame())
                hostTex = gs().hostFrameTexture(hostTexW, hostTexH, hostFullW, hostFullH);
            // Task 1a: the GL probe latched a failure on this machine. Hand the frame to the CPU
            // rasterizer -- the same backend PS2X_GS_BACKEND=cpu selects -- and leave a code the
            // launcher can turn into a sentence. Once; the swap makes hostDriven() false.
            if (GSGlBackend::glUnavailableForProcess())
            {
                std::cerr << "[gs-gl] switching to the CPU rasterizer: " << GSGlBackend::glMissingForProcess()
                          << std::endl;
                gs().setRasterBackend(std::make_unique<GSCpuBackend>());
                setPs2ProcessExitCode(GsGlCaps::kExitCode);
                hostTex = 0u;
            }
        }
        if (hostTex != 0u && hostTexW != 0u && hostTexH != 0u)
        {
            // The GL texture is the whole render target; the displayed frame is its top-left
            // hostTexW x hostTexH rectangle (srcRect below), so raylib must know the full size.
            presentTex.id = hostTex;
            presentTex.width = static_cast<int>(hostFullW ? hostFullW : hostTexW);
            presentTex.height = static_cast<int>(hostFullH ? hostFullH : hostTexH);
            presentTex.mipmaps = 1;
            presentTex.format = PIXELFORMAT_UNCOMPRESSED_R8G8B8A8;
            presentWidth = hostTexW;
            presentHeight = hostTexH;
        }
        else
        {
            UploadFrame(frameTex, this, presentWidth, presentHeight);
        }

        BeginDrawing();
        ClearBackground(BLACK);
        const float srcWidth = static_cast<float>(std::max<uint32_t>(1u, presentWidth));
        const float srcHeight = static_cast<float>(std::max<uint32_t>(1u, presentHeight));
        const float screenWidth = static_cast<float>(GetScreenWidth());
        const float screenHeight = static_cast<float>(GetScreenHeight());
        const float scale = std::min(screenWidth / srcWidth, screenHeight / srcHeight);
        const float dstWidth = srcWidth * scale;
        const float dstHeight = srcHeight * scale;
        const Rectangle srcRect{0.0f, 0.0f, srcWidth, srcHeight};
        const Rectangle dstRect{
            (screenWidth - dstWidth) * 0.5f,
            (screenHeight - dstHeight) * 0.5f,
            dstWidth,
            dstHeight};
        // PS2X_PRESENT_FILTER (read once) selects how the PS2 frame is stretched to the window:
        //   linear  - default, today's behaviour: one aspect-fit draw per read circuit, sampler
        //             state left exactly as whoever created the texture set it (the GL
        //             render-target copy is GL_LINEAR, the CPU fallback texture GL_NEAREST).
        //   point   - nearest sampling straight to the window: hard pixel edges, but the fit
        //             scale is fractional so the source pixels land on uneven numbers of texels.
        //   integer - point-sample the frame into an off-screen stage at k = floor(fit scale)
        //             times its size (exact pixel replication), then stretch that stage the
        //             remaining scale/k (in [1,2)) into the window with linear filtering.
        static const std::string s_presentFilter = [] {
            const char *e = ps2x::knob("PS2X_PRESENT_FILTER");
            std::string v(e ? e : "linear");
            if (v != "linear" && v != "integer" && v != "point")
            {
                // Falling back to the default is the safe direction, but say so: otherwise a typo
                // is indistinguishable from "the knob did nothing".
                std::cerr << "[present] PS2X_PRESENT_FILTER=\"" << v
                          << "\" is not linear|integer|point; presenting as linear" << std::endl;
                v = "linear";
            }
            return v;
        }();
        const bool integerPresent = (s_presentFilter == "integer");
        const bool pointSampled = integerPresent || (s_presentFilter == "point");
        // Only touch sampler state off the default path, so that "linear" is byte for byte what
        // the code did before this knob existed on both the host and the CPU present path.
        if (pointSampled)
            SetTextureFilter(presentTex, TEXTURE_FILTER_POINT);
        // Both branches draw the read circuits the same way, only into a different target:
        // circuit 1 unblended, because the GS frame's alpha channel is game data (often 0), and
        // the optional circuit 2 alpha-blended over it -- the PMODE merge of two read circuits
        // (movies letterbox over a black buffer this way), where the backend hands back circuit 2
        // with alpha = its weight so that standard alpha blending does C2*w + C1*(1-w).
        const auto drawCircuits = [&](const Rectangle &dst) {
            rlDrawRenderBatchActive();
            rlDisableColorBlend();
            DrawTexturePro(presentTex, srcRect, dst, Vector2{0.0f, 0.0f}, 0.0f, WHITE);
            rlDrawRenderBatchActive();
            rlEnableColorBlend();
            if (hostTex != 0u)
            {
                if (const uint32_t tex2 = gs().hostFrameTexture2())
                {
                    Texture2D presentTex2 = presentTex;
                    presentTex2.id = tex2;
                    // The overlay is its own GL texture and the backend creates it GL_LINEAR, so
                    // it needs the mode's filter as well: otherwise circuit 1 samples nearest and
                    // the overlay linear on exactly the frames where the two are composited.
                    if (pointSampled)
                        SetTextureFilter(presentTex2, TEXTURE_FILTER_POINT);
                    DrawTexturePro(presentTex2, srcRect, dst, Vector2{0.0f, 0.0f}, 0.0f, WHITE);
                    rlDrawRenderBatchActive();
                }
            }
        };
        if (integerPresent)
        {
            static RenderTexture2D s_integerStage{};
            static bool s_integerStageFailed = false;
            // scale is positive, so the truncation is the floor; k >= 1 keeps a window smaller
            // than the frame working (the stage is then 1:1 and the fit draw shrinks it).
            const int k = std::max(1, static_cast<int>(scale));
            const int stageW = static_cast<int>(srcWidth) * k;
            const int stageH = static_cast<int>(srcHeight) * k;
            if (!s_integerStageFailed &&
                (s_integerStage.texture.width != stageW || s_integerStage.texture.height != stageH))
            {
                if (s_integerStage.id != 0u)
                    UnloadRenderTexture(s_integerStage);
                s_integerStage = LoadRenderTexture(stageW, stageH);
                if (s_integerStage.id == 0u)
                {
                    // A failed load hands back {0}, whose width never matches: latch instead of
                    // retrying every frame, and present directly rather than letting
                    // BeginTextureMode(0) draw the stage into the window.
                    s_integerStageFailed = true;
                    std::cerr << "[present] LoadRenderTexture(" << stageW << "x" << stageH
                              << ") failed; PS2X_PRESENT_FILTER=integer falls back to the direct draw"
                              << std::endl;
                }
                else
                {
                    SetTextureFilter(s_integerStage.texture, TEXTURE_FILTER_BILINEAR);
                }
            }
            if (s_integerStage.id != 0u)
            {
                BeginTextureMode(s_integerStage);
                ClearBackground(BLACK);
                drawCircuits(Rectangle{0.0f, 0.0f, static_cast<float>(stageW), static_cast<float>(stageH)});
                EndTextureMode();
                // raylib render textures are y-flipped, hence the negative source height. The
                // merged frame still carries the GS alpha, so this draw is unblended like
                // circuit 1 above.
                rlDrawRenderBatchActive();
                rlDisableColorBlend();
                DrawTexturePro(s_integerStage.texture,
                               Rectangle{0.0f, 0.0f, static_cast<float>(stageW), -static_cast<float>(stageH)},
                               dstRect, Vector2{0.0f, 0.0f}, 0.0f, WHITE);
                rlDrawRenderBatchActive();
                rlEnableColorBlend();
            }
            else
            {
                drawCircuits(dstRect);
            }
        }
        else
        {
            drawCircuits(dstRect);
        }
        // PS2X_HOST_SCREENSHOT_LATEST=<file.png>: keep rewriting the current frame (GL readback,
        // every ~150 ms, atomic rename) so the parity harness can read it instead of PrintWindow,
        // which hands back a white bitmap whenever another window (a firewall prompt, Settings)
        // overlaps the GL window. Taken before the debug UI draws so its collapsed title bar does
        // not end up in the parity captures.
        {
            static const char *s_latestEnv = ps2x::knob("PS2X_HOST_SCREENSHOT_LATEST");
            if (s_latestEnv)
            {
                static double s_nextLatest = 0.5;
                const double now = GetTime();
                if (now >= s_nextLatest)
                {
                    s_nextLatest = now + 0.15;
                    const std::string finalPath(s_latestEnv);
                    const std::string tmpPath = finalPath + ".tmp.png";
                    Image shot = LoadImageFromScreen();
                    ExportImage(shot, tmpPath.c_str());
                    UnloadImage(shot);
                    std::error_code ec;
                    std::filesystem::rename(tmpPath, finalPath, ec);
                }
            }
        }
        // PS2X_FPS_OVERLAY=1 (Task 10): one line of raylib text in the top-left of the WINDOW. Drawn after the
        // exported frame above, so the gate's detectors and every parity capture see exactly what they saw
        // before this knob existed; the backing rectangle is 200x14, the box the task's bar allows.
        {
            static const bool s_fpsOverlay = [] {
                const char *const e = ps2x::knob("PS2X_FPS_OVERLAY");
                return e != nullptr && *e != 0 && std::strcmp(e, "0") != 0;
            }();
            if (s_fpsOverlay)
            {
                // The guest rate over the last second, from the same vsync counter the [pc-sampler] line's
                // vsync= field reads (game_overrides_socom2.cpp:682).
                static double s_windowStart = GetTime();
                static uint64_t s_windowTick = eeScheduler().currentVSyncTick();
                static double s_guestHz = -1.0;
                const double nowS = GetTime();
                const uint64_t tickNow = eeScheduler().currentVSyncTick();
                if (nowS - s_windowStart >= 1.0)
                {
                    s_guestHz = static_cast<double>(tickNow - s_windowTick) / (nowS - s_windowStart);
                    s_windowStart = nowS;
                    s_windowTick = tickNow;
                }
                const std::string line = fpsOverlayLine(GetFPS(), s_guestHz, GetFrameTime() * 1000.0);
                DrawRectangle(0, 0, 200, 14, Color{0, 0, 0, 160});
                DrawText(line.c_str(), 4, 2, 10, RAYWHITE);
            }
        }
        if (m_debugUiInitialized && m_debugUiDrawCallback)
        {
            m_debugUiDrawCallback(*this, m_debugUiUserData);
        }
        // PS2X_HOST_SCREENSHOT=<dir>[:<seconds>]: save what the window shows every <seconds> (default 5).
        {
            static const char *s_shotEnv = ps2x::knob("PS2X_HOST_SCREENSHOT");
            if (s_shotEnv)
            {
                static std::string s_dir;
                static double s_interval = 5.0;
                static double s_next = 1.0;
                static int s_index = 0;
                if (s_dir.empty())
                {
                    s_dir = s_shotEnv;
                    const size_t colon = s_dir.rfind(':');
                    if (colon != std::string::npos && colon > 1u)
                    {
                        s_interval = std::max(0.5, std::atof(s_dir.c_str() + colon + 1));
                        s_dir.resize(colon);
                    }
                }
                const double now = GetTime();
                if (now >= s_next)
                {
                    s_next = now + s_interval;
                    Image shot = LoadImageFromScreen();
                    char path[512];
                    std::snprintf(path, sizeof(path), "%s/host_%03d_%.0fs.png", s_dir.c_str(), s_index++, now);
                    ExportImage(shot, path);
                    UnloadImage(shot);
                }
            }
        }
        EndDrawing();

        if (WindowShouldClose())
        {
            RUNTIME_LOG("[run] window close requested, breaking out of loop");
            requestStop();
            break;
        }
    }

    // The GL thread no longer replays: wake a game thread waiting on GS back-pressure (R35) so
    // the join below cannot wait out the cap.
    gs().releaseHostBackpressure();
    requestStop();
    if (gameThread.joinable())
    {
        gameThread.join();
    }

    if (m_debugUiInitialized && m_debugUiShutdownCallback)
    {
        m_debugUiShutdownCallback(*this, m_debugUiUserData);
        m_debugUiInitialized = false;
    }
    UnloadTexture(frameTex);
    stopHostMic();
    ps2_stubs::socom2HostInputShutdown();   // review finding F12: the sampler thread, joined before we go
    CloseWindow();

    RUNTIME_LOG("[run] exiting loop");
}

// PS2X_FPU_TRAP=1: VU0 macro-mode overflow reporter (declared in ps2_runtime_macros.h).
void ps2_vu_trap_report(const char *what, __m128 v, const R5900Context *ctx)
{
    if (!ps2_fpu_trap_enabled() || !ctx || !ps2_fpu_trap_site_ok(ctx->pc))
        return;
    alignas(16) float lanes[4];
    _mm_store_ps(lanes, v);
    std::fprintf(stderr, "[vu-trap] %.3fs %s lanes=(%g,%g,%g,%g) pc=0x%x ra=0x%x\n", ps2_fpu_trap_time(), what, (double)lanes[0],
                 (double)lanes[1], (double)lanes[2], (double)lanes[3], ctx->pc, GPR_U32(ctx, 31));
}

// One shared per-site cap for the float traps (5 reports per guest pc).
bool ps2_fpu_trap_site_ok(uint32_t pc)
{
    static uint32_t s_pcs[256];
    static uint8_t s_counts[256];
    static int s_n = 0;
    for (int i = 0; i < s_n; ++i)
        if (s_pcs[i] == pc)
            return s_counts[i]++ < 5;
    if (s_n < 256)
    {
        s_pcs[s_n] = pc;
        s_counts[s_n] = 1;
        ++s_n;
        return true;
    }
    return false;
}

// ---------------------------------------------------------------------------------------------
// Sprint 11 Task 8b: the EE stub subsystems' state.
//
// Each object is a member of the runtime, so two PS2Runtime instances in one process share none
// of it. The ps2_stubs::*RuntimeStateFor(runtime) helpers are what the stubs call, because an EE
// stub can be reached with no runtime at all (TODO_NAMED, sceGsResetGraph, fopen/fclose and the
// libc rand pair all tolerate runtime == nullptr, and several tests use that); those calls share
// one process-wide fallback instance each, which is the only state here that is not per-runtime.
// ---------------------------------------------------------------------------------------------

ps2_stubs::StubLogRuntimeState &PS2Runtime::stubLogRuntimeState() { return *m_stubLogRuntimeState; }
const ps2_stubs::StubLogRuntimeState &PS2Runtime::stubLogRuntimeState() const { return *m_stubLogRuntimeState; }
ps2_stubs::DmaRuntimeState &PS2Runtime::dmaRuntimeState() { return *m_dmaRuntimeState; }
const ps2_stubs::DmaRuntimeState &PS2Runtime::dmaRuntimeState() const { return *m_dmaRuntimeState; }
ps2_stubs::GsRuntimeState &PS2Runtime::gsRuntimeState() { return *m_gsRuntimeState; }
const ps2_stubs::GsRuntimeState &PS2Runtime::gsRuntimeState() const { return *m_gsRuntimeState; }
ps2_stubs::LibCRuntimeState &PS2Runtime::libcRuntimeState() { return *m_libcRuntimeState; }
const ps2_stubs::LibCRuntimeState &PS2Runtime::libcRuntimeState() const { return *m_libcRuntimeState; }
ps2_stubs::CdRuntimeState &PS2Runtime::cdRuntimeState() { return *m_cdRuntimeState; }
const ps2_stubs::CdRuntimeState &PS2Runtime::cdRuntimeState() const { return *m_cdRuntimeState; }
ps2_stubs::IopHeapRuntimeState &PS2Runtime::iopHeapRuntimeState() { return *m_iopHeapRuntimeState; }
const ps2_stubs::IopHeapRuntimeState &PS2Runtime::iopHeapRuntimeState() const { return *m_iopHeapRuntimeState; }

void PS2Runtime::resetStubRuntimeState()
{
    m_stubLogRuntimeState->reset();
    m_dmaRuntimeState->reset();
    m_gsRuntimeState->reset();
    m_libcRuntimeState->reset();
    m_cdRuntimeState->reset();
    m_iopHeapRuntimeState->reset();
}

namespace ps2_stubs
{
    StubLogRuntimeState &stubLogRuntimeStateFor(PS2Runtime *runtime)
    {
        static StubLogRuntimeState noRuntimeFallback;
        return runtime ? runtime->stubLogRuntimeState() : noRuntimeFallback;
    }

    DmaRuntimeState &dmaRuntimeStateFor(PS2Runtime *runtime)
    {
        static DmaRuntimeState noRuntimeFallback;
        return runtime ? runtime->dmaRuntimeState() : noRuntimeFallback;
    }

    GsRuntimeState &gsRuntimeStateFor(PS2Runtime *runtime)
    {
        static GsRuntimeState noRuntimeFallback;
        return runtime ? runtime->gsRuntimeState() : noRuntimeFallback;
    }

    LibCRuntimeState &libcRuntimeStateFor(PS2Runtime *runtime)
    {
        static LibCRuntimeState noRuntimeFallback;
        return runtime ? runtime->libcRuntimeState() : noRuntimeFallback;
    }

    CdRuntimeState &cdRuntimeStateFor(PS2Runtime *runtime)
    {
        static CdRuntimeState noRuntimeFallback;
        return runtime ? runtime->cdRuntimeState() : noRuntimeFallback;
    }

    IopHeapRuntimeState &iopHeapRuntimeStateFor(PS2Runtime *runtime)
    {
        static IopHeapRuntimeState noRuntimeFallback;
        return runtime ? runtime->iopHeapRuntimeState() : noRuntimeFallback;
    }
}
